/**
 * Parsed-query regressions for inputs crossing a proven-safe UNION boundary. Besides preserving solution bags, these
 * tests observe the bindings delivered to the evaluator and the bound lookups made against the triple source.
 */
class UnionScopeInputPropagationTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static final String PREFIX = "PREFIX rdf: <" + RDF.NAMESPACE + "> ";
	private static final String SEED = "{ SELECT DISTINCT ?t WHERE { ?s a ?t } } ";
	private static final String PATH = "?r rdf:rest*/rdf:first ?t . ";
	private static final String LEFT_ARM = "{ ?k ?l ?m . ?m ?w ?r } ";
	private static final String RIGHT_ARM = "{ ?k ?l ?m . ?m ?w ?t } ";
	private static final String OUTSIDE = "?u <urn:outside> ?v . ";

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void unrelatedMandatoryJoinDoesNotHidePathInputsFromUnion(boolean outsideBeforeOptional) {
		String optional = "OPTIONAL { " + PATH + LEFT_ARM + "UNION " + RIGHT_ARM + "} ";
		String query = PREFIX + "SELECT * WHERE { " + SEED
				+ (outsideBeforeOptional ? OUTSIDE + optional : optional + OUTSIDE) + "}";
		List<Statement> data = pathData();
		List<BindingSet> expected = evaluate(parse(query), new RecordingTripleSource(data));
		RecordingTripleSource source = new RecordingTripleSource(data);
		RecordingStrategy strategy = new RecordingStrategy(source);
		TupleExpr optimized = strategy.optimize(parse(query), new EvaluationStatistics(),
				EmptyBindingSet.getInstance());
		Union union = onlyUnion(optimized);
		List<BindingSet> actual = evaluate(optimized, strategy);

		assertAll(
				() -> assertThat(expected).hasSize(12),
				() -> assertThat(actual).containsExactlyInAnyOrderElementsOf(expected),
				() -> assertThat(union.isVariableScopeChange())
						.as("an unrelated join outside OPTIONAL does not block its safe relational UNION")
						.isFalse(),
				() -> assertPathInputs(strategy, union),
				() -> assertThat(firstStatement(union.getLeftArg()).getObjectVar().getName()).isEqualTo("r"),
				() -> assertThat(firstStatement(union.getRightArg()).getObjectVar().getName()).isEqualTo("t"),
				() -> assertThat(source.requests.stream().filter(request -> request.predicate() == null).toList())
						.as("wildcard-predicate lookups have a bound endpoint")
						.isNotEmpty()
						.allSatisfy(request -> {
							// The zero-length part of rest* also probes graph membership with a bound subject.
							assertThat(request.subject() != null || request.object() != null).isTrue();
						}),
				() -> assertThat(source.requests)
						.as("a positive-length reverse path also supplies its head to the UNION")
						.anySatisfy(request -> {
							assertThat(request.predicate()).isNull();
							assertThat(request.object()).isEqualTo(iri("head1"));
						}));
	}

	@Test
	void nestedRelationalUnionsAcceptPathInputsInOnePass() {
		String nested = "{ " + LEFT_ARM + "UNION " + RIGHT_ARM + "} UNION " + LEFT_ARM;
		String query = PREFIX + "SELECT * WHERE { " + SEED + "OPTIONAL { " + PATH + nested + "} " + OUTSIDE + "}";
		List<Statement> data = pathData();
		List<BindingSet> expected = evaluate(parse(query), new RecordingTripleSource(data));
		TupleExpr scopeOnly = parse(query);
		List<Union> unions = unions(scopeOnly);
		assertThat(unions).hasSize(2).allSatisfy(union -> assertThat(union.isVariableScopeChange()).isTrue());

		UnionScopeChangeOptimizer optimizer = new UnionScopeChangeOptimizer();
		optimizer.optimize(scopeOnly, null, EmptyBindingSet.getInstance());
		RecordingStrategy strategy = new RecordingStrategy(new RecordingTripleSource(data));
		List<BindingSet> actual = evaluate(scopeOnly, strategy);
		String afterOnePass = scopeOnly.toString();
		optimizer.optimize(scopeOnly, null, EmptyBindingSet.getInstance());

		assertAll(
				() -> assertThat(expected).hasSize(16),
				() -> assertThat(actual).containsExactlyInAnyOrderElementsOf(expected),
				() -> assertThat(unions).allSatisfy(union -> assertThat(union.isVariableScopeChange()).isFalse()),
				() -> assertThat(unions).allSatisfy(union -> assertPathInputs(strategy, union)),
				() -> assertThat(scopeOnly.toString()).as("scope analysis reaches a stable result in one pass")
						.isEqualTo(afterOnePass));
	}

	@Test
	void nullableInputsAndDuplicateUnionRowsRetainTheirBag() {
		String query = """
				SELECT ?r ?value ?tag WHERE {
				  VALUES ?r { <urn:r1> <urn:r1> UNDEF }
				  OPTIONAL {
				    { VALUES (?r ?value) { (<urn:r1> <urn:v1>) (UNDEF <urn:v0>) } }
				    UNION
				    { VALUES ?tag { <urn:tag> <urn:tag> } }
				  }
				  ?u <urn:outside> ?v .
				}
				""";
		List<Statement> data = List.of(statement("outsideSubject", "outside", "outsideObject"));
		List<BindingSet> expected = List.of(
				row("r", "r1", "value", "v1"), row("r", "r1", "value", "v1"), row("r", "r1", "value", "v1"),
				row("r", "r1", "value", "v0"), row("r", "r1", "value", "v0"),
				row("r", "r1", "tag", "tag"), row("r", "r1", "tag", "tag"),
				row("r", "r1", "tag", "tag"), row("r", "r1", "tag", "tag"),
				row("value", "v0"), row("tag", "tag"), row("tag", "tag"));
		assertThat(evaluate(parse(query), new RecordingTripleSource(data)))
				.containsExactlyInAnyOrderElementsOf(expected);

		TupleExpr scopeOnly = parse(query);
		Union union = onlyUnion(scopeOnly);
		new UnionScopeChangeOptimizer().optimize(scopeOnly, null, EmptyBindingSet.getInstance());
		RecordingStrategy scopeStrategy = new RecordingStrategy(new RecordingTripleSource(data));
		List<BindingSet> scopeRows = evaluate(scopeOnly, scopeStrategy);
		RecordingStrategy fullStrategy = new RecordingStrategy(new RecordingTripleSource(data));
		TupleExpr fullyOptimized = fullStrategy.optimize(parse(query), new EvaluationStatistics(),
				EmptyBindingSet.getInstance());
		List<BindingSet> fullRows = evaluate(fullyOptimized, fullStrategy);

		assertAll(
				() -> assertThat(union.isVariableScopeChange()).isFalse(),
				() -> assertThat(scopeRows).containsExactlyInAnyOrderElementsOf(expected),
				() -> assertThat(fullRows).containsExactlyInAnyOrderElementsOf(expected),
				() -> assertThat(scopeStrategy.inputs.get(union))
						.as("nullable input is preserved rather than treated as guaranteed")
						.anySatisfy(input -> assertThat(input.hasBinding("r")).isTrue())
						.anySatisfy(input -> assertThat(input.hasBinding("r")).isFalse()));
	}

	@Test
	void subqueryJoinReorderingRetainsSelectedPathBindingsInBothUnionArms() {
		String query = """
				SELECT ?end ?v1 ?v2 WHERE {
				  {
				    SELECT ?end ?v1 ?v2 WHERE {
				      { ?end <urn:wide1> ?v1 . ?other1 <urn:rare1> <urn:w1> }
				      UNION
				      { ?end <urn:wide2> ?v2 . ?other2 <urn:rare2> <urn:w2> }
				      <urn:start> <urn:step>+ ?end .
				    }
				  }
				}
				""";
		List<Statement> data = List.of(
				statement("start", "step", "endValue"),
				statement("endValue", "wide1", "value1"),
				statement("other1", "rare1", "w1"),
				statement("endValue", "wide2", "value2"),
				statement("other2", "rare2", "w2"));
		List<BindingSet> expected = List.of(row("end", "endValue", "v1", "value1"),
				row("end", "endValue", "v2", "value2"));
		assertThat(evaluate(parse(query), new RecordingTripleSource(data)))
				.containsExactlyInAnyOrderElementsOf(expected);

		RecordingTripleSource source = new RecordingTripleSource(data);
		RecordingStrategy strategy = new RecordingStrategy(source);
		TupleExpr optimized = strategy.optimize(parse(query), new EvaluationStatistics(),
				EmptyBindingSet.getInstance());
		Union union = onlyUnion(optimized);
		List<BindingSet> actual = evaluate(optimized, strategy);

		assertAll(
				() -> assertThat(actual).containsExactlyInAnyOrderElementsOf(expected),
				() -> assertThat(union.isVariableScopeChange()).isFalse(),
				() -> assertThat(strategy.inputs.get(union)).isNotEmpty()
						.allSatisfy(input -> assertThat(input.getValue("end")).isEqualTo(iri("endValue"))),
				() -> assertThat(firstStatement(union.getLeftArg()).getPredicateVar().getValue())
						.as("the first arm uses the endpoint selected before UNION")
						.isEqualTo(iri("wide1")),
				() -> assertThat(firstStatement(union.getRightArg()).getPredicateVar().getValue())
						.as("rewriting the first arm does not discard the selected endpoint for the second")
						.isEqualTo(iri("wide2")),
				() -> assertEndpointLookupFirst(source, "wide1", "rare1"),
				() -> assertEndpointLookupFirst(source, "wide2", "rare2"));
	}

	private static void assertEndpointLookupFirst(RecordingTripleSource source, String endpointPredicate,
			String independentPredicate) {
		List<StatementRequest> branchRequests = source.requests.stream()
				.filter(request -> iri(endpointPredicate).equals(request.predicate())
						|| iri(independentPredicate).equals(request.predicate()))
				.toList();
		assertThat(branchRequests).as("actual statement lookups in the UNION arm").isNotEmpty();
		assertThat(branchRequests.getFirst().predicate()).isEqualTo(iri(endpointPredicate));
		assertThat(branchRequests.getFirst().subject()).isEqualTo(iri("endValue"));
	}

	private static void assertPathInputs(RecordingStrategy strategy, Union union) {
		assertThat(strategy.inputs.get(union)).as("actual incoming bindings at UNION")
				.isNotEmpty()
				.allSatisfy(input -> assertThat(input.getBindingNames()).contains("r", "t"));
		assertThat(strategy.inputs.get(union)).anySatisfy(input -> {
			assertThat(input.getValue("r")).isEqualTo(iri("head1"));
			assertThat(input.getValue("t")).isEqualTo(iri("T1"));
		});
	}

	private static QueryRoot parse(String query) {
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		return expression instanceof QueryRoot root ? root : new QueryRoot(expression);
	}

	private static List<Union> unions(TupleExpr expression) {
		List<Union> unions = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Union union) {
				unions.add(union);
				super.meet(union);
			}
		});
		return unions;
	}

	private static Union onlyUnion(TupleExpr expression) {
		List<Union> unions = unions(expression);
		assertThat(unions).hasSize(1);
		return unions.getFirst();
	}

	private static StatementPattern firstStatement(TupleExpr expression) {
		List<StatementPattern> statements = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern statement) {
				statements.add(statement);
			}
		});
		assertThat(statements).isNotEmpty();
		return statements.getFirst();
	}

	private static List<BindingSet> evaluate(TupleExpr expression, RecordingTripleSource source) {
		return evaluate(expression, new RecordingStrategy(source));
	}

	private static List<BindingSet> evaluate(TupleExpr expression, RecordingStrategy strategy) {
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> results = strategy.precompile(expression)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (results.hasNext()) {
				rows.add(new QueryBindingSet(results.next()));
			}
		}
		return rows;
	}

	private static List<Statement> pathData() {
		List<Statement> data = new ArrayList<>();
		for (int i = 1; i <= 2; i++) {
			data.add(VF.createStatement(iri("s" + i), RDF.TYPE, iri("T" + i)));
			data.add(VF.createStatement(iri("r" + i), RDF.FIRST, iri("T" + i)));
			data.add(VF.createStatement(iri("r" + i), RDF.REST, RDF.NIL));
			data.add(statement("k" + i, "l", "m" + i));
			data.add(statement("m" + i, "w", "r" + i));
			data.add(statement("m" + i, "w", "T" + i));
		}
		data.add(VF.createStatement(iri("head1"), RDF.REST, iri("r1")));
		data.add(statement("kh", "l", "mh"));
		data.add(statement("mh", "w", "head1"));
		data.add(statement("outsideSubject", "outside", "outsideObject"));
		return List.copyOf(data);
	}

	private static IRI iri(String localName) {
		return VF.createIRI("urn:" + localName);
	}

	private static Statement statement(String subject, String predicate, String object) {
		return VF.createStatement(iri(subject), iri(predicate), iri(object));
	}

	private static BindingSet row(String... namesAndValues) {
		MapBindingSet row = new MapBindingSet();
		for (int i = 0; i < namesAndValues.length; i += 2) {
			row.addBinding(namesAndValues[i], iri(namesAndValues[i + 1]));
		}
		return row;
	}

	private record StatementRequest(Resource subject, IRI predicate, Value object) {
	}

	private static final class RecordingTripleSource implements TripleSource {

		private final List<Statement> statements;
		private final List<StatementRequest> requests = new ArrayList<>();

		private RecordingTripleSource(List<Statement> statements) {
			this.statements = statements;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			requests.add(new StatementRequest(subject, predicate, object));
			return new CloseableIteratorIteration<>(statements.stream()
					.filter(statement -> subject == null || subject.equals(statement.getSubject()))
					.filter(statement -> predicate == null || predicate.equals(statement.getPredicate()))
					.filter(statement -> object == null || object.equals(statement.getObject()))
					.filter(statement -> contexts == null || contexts.length == 0 || Arrays.stream(contexts)
							.anyMatch(context -> Objects.equals(context, statement.getContext())))
					.iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}
	}

	private static final class RecordingStrategy extends DefaultEvaluationStrategy {

		private final Map<Union, List<BindingSet>> inputs = new IdentityHashMap<>();

		private RecordingStrategy(TripleSource tripleSource) {
			super(tripleSource, null);
		}

		@Override
		protected QueryEvaluationStep prepare(Union union, QueryEvaluationContext context) {
			QueryEvaluationStep delegate = super.prepare(union, context);
			List<BindingSet> incoming = new ArrayList<>();
			inputs.put(union, incoming);
			return bindings -> {
				incoming.add(new QueryBindingSet(bindings));
				return delegate.evaluate(bindings);
			};
		}
	}
}
